t) AND (cycle_started_at <= started_at)), CONSTRAINT "billing_segments_proration_ratio_check" CHECK ((proration_ratio >= (0)::numeric) AND (proration_ratio <= (1)::numeric)), CONSTRAINT "billing_segments_rate_check" CHECK ((rate_card_rate_id IS NOT NULL) OR (rate_phase_id IS NOT NULL)), CONSTRAINT "billing_segments_status_check" CHECK (status = ANY (ARRAY['pending'::text, 'processing'::text, 'done'::text, 'failed'::text])));
