CREATE TABLE "x402_settlements" ("organization_id" uuid NOT NULL, "id" uuid NOT NULL, "x402_connection_id" uuid NOT NULL, "customer_id" uuid NULL, "subscription_id" uuid NULL, "wallet_transaction_id" uuid NULL, "payment_id" uuid NULL, "invoice_id" uuid NULL, "kind" text NOT NULL, "status" text NOT NULL DEFAULT 'pending', "settled_by" text NOT NULL DEFAULT 'tanvo', "network" text NOT NULL, "asset" text NOT NULL, "payer_address" text NOT NULL, "payee_address" text NOT NULL, "settled_amount_atomic" numeric(38) NOT NULL, "settled_amount_cents" bigint NOT NULL, "transaction_hash" text NULL, "reconcile_after" timestamptz NULL, "payment_digest" text NOT NULL, "purchase_settings" jsonb NULL, "payload" jsonb NOT NULL DEFAULT '{}', "error_reason" text NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("organization_id", "id"), CONSTRAINT "x402_settlements_connection_fkey" FOREIGN KEY ("organization_id", "x402_connection_id") REFERENCES "x402_connections" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "x402_settlements_customer_fkey" FOREIGN KEY ("organization_id", "customer_id") REFERENCES "customers" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "x402_settlements_invoice_fkey" FOREIGN KEY ("organization_id", "invoice_id") REFERENCES "invoices" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "x402_settlements_organization_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "x402_settlements_payment_fkey" FOREIGN KEY ("organization_id", "payment_id") REFERENCES "payments" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "x402_settlements_subscription_fkey" FOREIGN KEY ("organization_id", "subscription_id") REFERENCES "subscriptions" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "x402_settlements_wallet_transaction_fkey" FOREIGN KEY ("organization_id", "wallet_transaction_id") REFERENCES "wallet_transactions" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "x402_settlements_amount_positive_check" CHECK (settled_amount_atomic > (0)::numeric), CONSTRAINT "x402_settlements_credit_purchase_has_settings_check" CHECK ((kind <> 'credit_purchase'::text) OR (purchase_settings IS NOT NULL)), CONSTRAINT "x402_settlements_granted_has_subscription_check" CHECK ((wallet_transaction_id IS NULL) OR (subscription_id IS NOT NULL)), CONSTRAINT "x402_settlements_invoice_payment_has_invoice_check" CHECK ((kind <> 'invoice_payment'::text) OR (invoice_id IS NOT NULL)), CONSTRAINT "x402_settlements_kind_check" CHECK (kind = ANY (ARRAY['credit_purchase'::text, 'invoice_payment'::text])), CONSTRAINT "x402_settlements_merchant_settled_credit_purchase_check" CHECK ((settled_by = 'tanvo'::text) OR ((kind = 'credit_purchase'::text) AND (status = 'settled'::text))), CONSTRAINT "x402_settlements_payload_check" CHECK (jsonb_typeof(payload) = 'object'::text), CONSTRAINT "x402_settlements_pending_has_reconcile_after_check" CHECK ((status <> 'pending'::text) OR (reconcile_after IS NOT NULL)), CONSTRAINT "x402_settlements_purchase_settings_check" CHECK ((purchase_settings IS NULL) OR (jsonb_typeof(purchase_settings) = 'object'::text)), CONSTRAINT "x402_settlements_settled_by_check" CHECK (settled_by = ANY (ARRAY['tanvo'::text, 'merchant'::text])), CONSTRAINT "x402_settlements_settled_has_hash_check" CHECK ((status <> 'settled'::text) OR (transaction_hash IS NOT NULL)), CONSTRAINT "x402_settlements_status_check" CHECK (status = ANY (ARRAY['pending'::text, 'settled'::text, 'failed'::text])));
